import Foundation

struct Lesson: Identifiable {
    let module, id, title, concept, example, practice, question: String
    let choices: [String]
    let answer: Int
    let explanation: String
}

enum Course {
    static let modules = ["Foundations", "Calibration", "Offline editing", "Log analysis", "Professional review"]
    static let lessons = [
        Lesson(module: "Foundations", id: "engine", title: "Follow one engine cycle",
               concept: "An engine control unit (ECU) reads sensors, uses calibration tables to choose commands, and drives actuators. On a four-stroke engine the piston draws in a charge, compresses it, receives work from combustion, then expels exhaust. RPM measures crankshaft speed. Load describes how much the engine is being asked to deliver at that speed.",
               example: "A car can cruise downhill or climb a hill at 2,500 RPM. The crankshaft turns at the same speed in both cases, but the air charge can be very different.",
               practice: "Draw three boxes for sensor, ECU and actuator. Place a manifold pressure sensor, a fuel table and an injector in the appropriate boxes.",
               question: "Which pair can distinguish these two operating points?", choices: ["RPM and the file name","RPM and an appropriate load signal"], answer: 1,
               explanation: "A speed reading alone cannot distinguish the two air charges."),
        Lesson(module: "Foundations", id: "files", title: "Separate the tune from the log",
               concept: "A tune stores settings. A log records time-stamped observations. A backup captures the starting tune so later edits can be traced. OpenLink edits local files and reads a compatible ECU over USB. Saving a file changes the copy on your Mac.",
               example: "You have baseline.pclx, review.pclx and idle.csv. Use the first file as a reference, the second as a working copy and the CSV as a record of what happened.",
               practice: "Make a three-line inventory for those files. Record which one you would keep untouched and which one could tell you when a symptom started.",
               question: "Which file would you inspect for a brief throttle dropout?", choices: ["idle.csv","baseline.pclx"], answer: 0,
               explanation: "The time series can show a dropout. A calibration contains no timeline of that event."),
        Lesson(module: "Foundations", id: "units", title: "Read sensors and units",
               concept: "Manifold absolute pressure (MAP) uses vacuum as its zero. Gauge pressure uses the surrounding atmosphere as its zero. Before interpreting a value, identify the channel, its unit and its reference. Coolant and inlet-air temperatures describe different parts of the engine.",
               example: "At key-on with the engine stopped, the manifold is at 97 kPa absolute and barometric pressure is 97 kPa absolute. Gauge pressure is 97 − 97 = 0 kPa.",
               practice: "Repeat the calculation with MAP of 135 kPa absolute and barometric pressure of 95 kPa absolute. Write both reference points beside your answer.",
               question: "What gauge pressure does the second example represent?", choices: ["135 kPa","40 kPa"], answer: 1,
               explanation: "Subtract the local barometric pressure from the absolute reading. A fixed sea-level assumption introduces error."),
        Lesson(module: "Foundations", id: "tables", title: "Find an operating point",
               concept: "Read both axis titles, both units and the cell unit before interpreting a table. A highlighted cell is an editor selection. The engine may operate between breakpoints, so the four surrounding cells can all affect an interpolated result.",
               example: "A teaching grid has RPM columns of 2,000 and 3,000, and load rows of 40 and 60 kPa. The lower-load row contains 10 and 14 units. The higher-load row contains 18 and 22.",
               practice: "Draw the grid. At 2,500 RPM, interpolate halfway across each row to get 12 and 20. Now move halfway between the rows to represent 50 kPa.",
               question: "What value does this bilinear example produce?", choices: ["20 units","16 units"], answer: 1,
               explanation: "Halfway between 12 and 20 is 16. These are illustrative values for learning the lookup."),
        Lesson(module: "Calibration", id: "fuel", title: "Understand the fuel model",
               concept: "Fuel delivery depends on the selected equation. In Link’s modelled mode the ECU uses volumetric efficiency, engine capacity, injector characteristics, fuel properties and other inputs. A traditional fuel table has a different interpretation. Identify the equation before comparing numbers across files.",
               example: "Two files both show 75 in a fuel table. One is modelled and the other traditional. Equal cell values alone do not establish equal injector pulse widths.",
               practice: "Build a comparison checklist containing equation, axes, injector data and fuel pressure reference. Explain why the same number could produce different commands.",
               question: "What should you establish before interpreting the cell?", choices: ["The equation and units used by the file","Whether the cell has the same colour"], answer: 0,
               explanation: "A heat map describes relative values in its own view. The fuel equation defines how a value contributes to delivery."),
        Lesson(module: "Calibration", id: "lambda", title: "Compare target and measured lambda",
               concept: "Lambda expresses air–fuel ratio relative to the stoichiometric ratio for the fuel. A lower value is richer. A target is a request and a wideband reading is a measurement. Sensor delay, an exhaust leak or a transient can separate them even when the table is appropriate.",
               example: "During a steady interval the target is 0.95 and measured lambda is 1.00. The measured mixture is leaner than requested. This observation alone does not identify its cause.",
               practice: "Write the difference in lambda units. List two checks that would make the measurement more credible, such as sensor status and a repeat at matching load.",
               question: "Which conclusion does this evidence support?", choices: ["The fuel table must be increased by 0.05","Measured lambda is 0.05 above target"], answer: 1,
               explanation: "A difference between readings has lambda units. It does not identify which input or calibration caused it."),
        Lesson(module: "Calibration", id: "spark", title: "Trace ignition and knock control",
               concept: "Ignition advance describes spark timing relative to crankshaft position. A base table supplies one input to the commanded angle. Temperature corrections and knock control may change the final command. Knock is abnormal combustion and a knock channel requires engine-specific interpretation.",
               example: "An archived log lists base advance of 18°, a temperature trim of −2° and final timing of 16°. The difference is accounted for by a recorded correction.",
               practice: "Sketch the signal chain from base angle through trim to final command. Name the evidence you would need before attributing a different event to knock.",
               question: "Does this two-degree difference establish knock?", choices: ["Yes, every timing reduction indicates knock","No, the recorded temperature trim explains it"], answer: 1,
               explanation: "Use the active correction channels and their timestamps to attribute the timing change."),
        Lesson(module: "Calibration", id: "control", title: "Read a feedback loop",
               concept: "A feedback controller compares a target with a measurement and adjusts an output. The target, the measured response and the actuator command are three separate signals. Output limits can prevent the controller from reaching a target. Delays can make a response appear late.",
               example: "In an illustrative idle trace the target is 900 RPM, actual speed is 780 RPM and idle actuator output is already at its configured upper limit.",
               practice: "Draw three aligned traces. Label when the output first reaches its limit and what happens to the error afterward. State one mechanical or sensor check before considering controller gains.",
               question: "What is established by this trace?", choices: ["The output reached its configured limit","The proportional gain must be too small"], answer: 0,
               explanation: "A saturated output cannot increase further. The cause of the speed error still needs investigation."),
        Lesson(module: "Offline editing", id: "baseline", title: "Create a reversible working copy",
               concept: "Keep the starting tune and the working file separate. A useful revision name records its relationship to a baseline. Include the ECU identity and firmware in your notes so another person can reproduce the comparison.",
               example: "In Finder, duplicate your own tune as review-01. Open the duplicate in Tune workspace. The overview identifies the ECU and firmware. Use Compare to select the original.",
               practice: "Record the file names and ECU identity. With two identical copies you should see zero differences. If you have no tune, write a revision inventory for the fictional baseline and review files from lesson two.",
               question: "What should a comparison of two identical copies report?", choices: ["One difference for the new file name","Zero differences"], answer: 1,
               explanation: "The comparison evaluates tune parameters. A separate file name lets you preserve the reference."),
        Lesson(module: "Offline editing", id: "edit", title: "Edit and verify a table",
               concept: "The table editor supports a selected cell or range. Set replaces the selection with an absolute value. Scale applies a percentage to existing values. Undo reverses an operation. Check the selection and unit before committing a change.",
               example: "On paper, start with two adjacent cells containing 40 and 60 units. A 10% scale yields 44 and 66. Setting both to 10 would instead produce 10 and 10.",
               practice: "Reproduce this on paper or use a disposable copy of a tune. Inspect the changed cells, undo, and verify the baseline values return. Never use these example values as engine targets.",
               question: "Which operation preserves the ratio between 40 and 60 here?", choices: ["Set both to 10","Scale both by 10%"], answer: 1,
               explanation: "Multiplying both cells by 1.10 preserves their 2-to-3 ratio."),
        Lesson(module: "Offline editing", id: "interpolate", title: "Use interpolation with uneven axes",
               concept: "An axis-weighted interpolation follows physical distance between breakpoints. This matters when adjacent columns are unequally spaced. Smoothing instead averages nearby values and can erase an intentional feature.",
               example: "A row has breakpoints at 1,000, 1,500 and 3,000 RPM. The outer cells hold 20 and 40 teaching units. The middle column lies one quarter of the way across the span.",
               practice: "Calculate the middle value as 20 + (40 − 20) × (500 ÷ 2,000). Sketch the row before and after. Identify what evidence would justify replacing the original middle value.",
               question: "Which middle value follows the RPM axis?", choices: ["25 units","30 units"], answer: 0,
               explanation: "The middle column in screen order is only a quarter of the way across the physical axis."),
        Lesson(module: "Offline editing", id: "diff", title: "Audit a revision cell by cell",
               concept: "OpenLink’s Difference view shows the compared cell minus the open cell. Write down which file occupies each side. Confirm the axis breakpoints as well as the values. Equal row and column positions can describe different conditions in two files.",
               example: "The open file contains 48 units. The reference contains 45. Difference shows −3. Relative to the reference, the open file has increased by 3 units.",
               practice: "Create a change record with the two file names, both axis coordinates, old value, new value and reason. Add an explicit note if either axis has moved.",
               question: "Which value belongs in the new-value column for the open revision?", choices: ["−3","48"], answer: 1,
               explanation: "The signed delta describes a comparison. The revision itself contains 48."),
        Lesson(module: "Log analysis", id: "capture", title: "Design a useful capture",
               concept: "Start with a question and choose the channels that could answer it. Include time, operating point, command and response. Preserve the original CSV. On the Mac, Live data & logs contains recording and import. A phone can view logs once approved on the Mac.",
               example: "To investigate a speed dip after throttle closure, an RPM-only trace shows the symptom. Adding throttle, target idle speed and available control channels gives the event context.",
               practice: "Write a capture plan naming the event, channels, units and the interval before and after it. Use an existing recording for practice. Mark any channels your setup cannot provide.",
               question: "Which plan best identifies when the dip began?", choices: ["Save only the minimum RPM","Keep timestamped samples from before and after closure"], answer: 1,
               explanation: "The minimum discards event order and hides whether the throttle moved before the dip."),
        Lesson(module: "Log analysis", id: "quality", title: "Recognize missing evidence",
               concept: "Sample spacing limits which events a log can resolve. Treat a missing value as unknown. Averaging across a gap can hide a transient, and substituting zero can invent one. Preserve the timestamps when comparing traces.",
               example: "A log contains RPM samples at 0.0, 0.1 and 0.5 seconds. They read 1,000, 990 and 1,000. The final interval spans four times the first.",
               practice: "Sketch the three points without joining the last two. Mark the interval in which a brief dip could be hidden. Describe what a higher-rate repeat might establish.",
               question: "Can these samples rule out a short dip at 0.3 seconds?", choices: ["No, that instant lies in the unsampled gap","Yes, the endpoints are close"], answer: 0,
               explanation: "Similar endpoints do not constrain every value between the samples."),
        Lesson(module: "Log analysis", id: "diagnose", title: "Test competing explanations",
               concept: "Separate the symptom from its cause. Form two hypotheses that predict different observations. Choose the least disruptive measurement that can distinguish them. If a required channel is unavailable, keep the conclusion provisional.",
               example: "Two recordings differ in measured lambda. One explanation is a change in fuel delivery. Another is that the recordings cover different temperatures and load. Comparing the overall averages mixes those conditions.",
               practice: "Define a matched window using RPM, load and temperature. Compare target and actual lambda inside it. Record what additional evidence would distinguish a fuel pressure change from a measurement error.",
               question: "Which comparison tests the delivery hypothesis more directly?", choices: ["The average lambda of each entire session","Matched operating windows with target and actual values"], answer: 1,
               explanation: "Matching operating conditions removes a major alternative explanation."),
        Lesson(module: "Professional review", id: "limits", title: "Review protection and test boundaries",
               concept: "Professional calibration integrates mechanical inspection, calibrated instrumentation and controlled testing. A tune file can show a configured limit. Verifying that a protection actually operates requires a supervised validation plan, suitable instrumentation and engine-specific acceptance criteria.",
               example: "A review file contains an oil-pressure protection threshold. The log contains RPM but no pressure channel and no protection status. A clean run through that file cannot demonstrate that protection operated.",
               practice: "Write a validation plan listing the sensor and units, calibration reference, enabling conditions, relevant status channels, stop criteria and the responsible qualified operator. Keep it as a review exercise.",
               question: "What can you sign off from this file and log?", choices: ["The engine is protected under all loads","The threshold is configured; operation remains unverified"], answer: 1,
               explanation: "Configuration and functional evidence answer different questions. Missing channels belong in the handoff."),
        Lesson(module: "Professional review", id: "handoff", title: "Build a calibration handoff",
               concept: "A reviewer needs a baseline, candidate, reason for each change and evidence of its effect. Keep an unmodified original, identify firmware, include the comparison report and link observations to precise log intervals. Record who owns each unresolved question.",
               example: "A report says that idle improved. A reproducible statement gives the two file revisions, warm operating conditions, target RPM, time window and measured variation in both recordings.",
               practice: "Draft a five-line handoff covering baseline, change, evidence, limitation and rollback file. Include one explicit decision that requires an instrumented dyno session with an experienced calibrator.",
               question: "Which statement makes the result reproducible?", choices: ["Name the revisions, conditions, interval and metric","Describe the new tune as smoother"], answer: 0,
               explanation: "A second reviewer can repeat the comparison using the same inputs and criteria."),
        Lesson(module: "Professional review", id: "capstone", title: "Capstone: approve or hold a revision",
               concept: "Review a fictional delivery before releasing it. Baseline A and candidate B use the same model and firmware. One fuel table cell differs. The author claims B corrected a lean reading. Your job is to decide what the files and logs actually establish.",
               example: "At 2,000 RPM and 50 kPa the cell is 60 in A and 63 in B. Log A shows target 1.00, measured 1.04 at 85 °C coolant. Log B shows target 1.00, measured 1.01 at 43 °C. The log lacks warm-up correction and fuel pressure.",
               practice: "Write your review in the notebook. Include the cell change in percent, both lambda errors, the unmatched condition, two missing channels, a matched retest and a release decision. Check your math against +5%, +0.04 and +0.01.",
               question: "What release decision is justified by the supplied evidence?", choices: ["Approve because the second lambda reading is closer","Hold the causal claim and request matched evidence"], answer: 1,
               explanation: "B measured closer to target, but coolant temperature changed and relevant corrections are missing. A defensible review preserves A, documents B and requests a matched repeat.")
    ]
}
